"""Handwritten Chinese characters generated by a fine-tuned SDT model.

Optional: needs ``pip install handnote[model]`` (torch, torchvision, einops).
Nothing in the rest of handnote imports this package at module level.

- :mod:`.weights`: download and cache the SDT checkpoint and content glyphs.
- :mod:`.sdt`: the network (vendored from SDT, MIT).
- :mod:`.data`: captures -> style images and training sequences.
- :mod:`.train`: fine-tune on one writer's strokes.
- :mod:`.generate`: write characters, check them and place them in cells.
- :mod:`.pressure`: pen pressure for generated strokes (numpy only).
"""

from __future__ import annotations


def torch_available() -> bool:
    """Whether the optional model dependencies are installed."""
    try:
        import einops  # noqa: F401
        import torch  # noqa: F401
        import torchvision  # noqa: F401
    except ImportError:
        return False
    return True
